4	/// the `Left` side (RNF09, FR-004). Covers all 13 of the backend's closed
5	/// error codes (contracts/failure-taxonomy.md) — domain-layer only, no
6	/// `package:flutter` import (RNF06).
7	sealed class Failure extends Equatable {
8	  const Failure({required this.message, required this.requestId});
9	
10	  final String message;
11	  final String requestId;
12	
13	  bool get retryable;
14	  String get code;
15	
16	  @override
17	  List<Object?> get props => [code, message, requestId];
18	}
19	
20	class AuthExpiredFailure extends Failure {
21	  const AuthExpiredFailure({required super.message, required super.requestId});
22	
23	  @override
24	  bool get retryable => false;
25	
26	  @override
27	  String get code => 'AUTH_EXPIRED';
28	}
29	
30	class AuthInvalidFailure extends Failure {
31	  const AuthInvalidFailure({required super.message, required super.requestId});
32	
33	  @override
34	  bool get retryable => false;
35	
36	  @override
37	  String get code => 'AUTH_INVALID';
38	}
39	
40	class NetworkTimeoutFailure extends Failure {
41	  const NetworkTimeoutFailure({
42	    required super.message,
43	    required super.requestId,
44	  });
45	
46	  @override
47	  bool get retryable => true;
48	
49	  @override
50	  String get code => 'NETWORK_TIMEOUT';
51	}
