import 'dart:convert';

import 'package:cerne/features/chat/domain/entities/chat_message.dart';
import 'package:cerne/features/chat/domain/entities/chat_session.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for chat (research.md R4) —
/// Keychain-backed, same pattern `EntriesLocalCache` already establishes.
/// Four **independent** storage keys so one write never clobbers another.
class ChatLocalCache {
  ChatLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _sessionsKey = 'chatSessionsLocalCache';
  static const _messagesKey = 'chatMessagesLocalCache';
  static const _lastActiveKey = 'chatLastActiveSessionId';
  static const _savedMessageEntryIdsKey = 'chatSavedMessageEntryIds';

  Future<List<ChatSession>> readSessions() async {
    final raw = await _storage.read(key: _sessionsKey);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded
          .map((e) => _sessionFromJson(e as Map<String, dynamic>))
          .toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeSessions(List<ChatSession> sessions) {
    final encoded = jsonEncode(sessions.map(_sessionToJson).toList());
    return _storage.write(key: _sessionsKey, value: encoded);
  }

  Future<Map<String, List<ChatMessage>>> readAllMessages() async {
    final raw = await _storage.read(key: _messagesKey);
    if (raw == null) return const {};
    try {
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      return decoded.map(
        (sessionId, messages) => MapEntry(
          sessionId,
          (messages as List<dynamic>)
              .map((m) => _messageFromJson(m as Map<String, dynamic>))
              .toList(),
        ),
      );
    } on FormatException {
      return const {};
    } on TypeError {
      return const {};
    }
  }

  Future<void> writeMessagesForSession(
    String sessionId,
    List<ChatMessage> messages,
  ) async {
    final all = await readAllMessages();
    final updated = {...all, sessionId: messages};
    final encoded = jsonEncode(
      updated.map(
        (sid, msgs) => MapEntry(sid, msgs.map(_messageToJson).toList()),
      ),
    );
    await _storage.write(key: _messagesKey, value: encoded);
  }

  Future<String?> readLastActiveSessionId() {
    return _storage.read(key: _lastActiveKey);
  }

  Future<void> writeLastActiveSessionId(String? sessionId) {
    if (sessionId == null) {
      return _storage.delete(key: _lastActiveKey);
    }
    return _storage.write(key: _lastActiveKey, value: sessionId);
  }

  Future<Map<String, String>> readSavedMessageEntryIds() async {
    final raw = await _storage.read(key: _savedMessageEntryIdsKey);
    if (raw == null) return const {};
    try {
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      return decoded.map((k, v) => MapEntry(k, v as String));
    } on FormatException {
      return const {};
    } on TypeError {
      return const {};
    }
  }

  Future<void> writeSavedMessageEntryIds(Map<String, String> ids) {
    return _storage.write(key: _savedMessageEntryIdsKey, value: jsonEncode(ids));
  }

  Map<String, dynamic> _sessionToJson(ChatSession s) => {
    'id': s.id,
    'title': s.title,
    'personaSnapshot': s.personaSnapshot.name,
    'userMessageCount': s.userMessageCount,
    'lastUserMessageAt': s.lastUserMessageAt?.toUtc().toIso8601String(),
    'createdAt': s.createdAt.toUtc().toIso8601String(),
    'updatedAt': s.updatedAt.toUtc().toIso8601String(),
  };

  ChatSession _sessionFromJson(Map<String, dynamic> data) => ChatSession(
    id: data['id'] as String,
    title: data['title'] as String,
    personaSnapshot: ChatPersona.values.byName(
      data['personaSnapshot'] as String,
    ),
    userMessageCount: data['userMessageCount'] as int,
    lastUserMessageAt: (data['lastUserMessageAt'] as String?) == null
        ? null
        : DateTime.parse(data['lastUserMessageAt'] as String),
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
  );

  Map<String, dynamic> _messageToJson(ChatMessage m) => {
    'id': m.id,
    'sessionId': m.sessionId,
    'role': m.role.name,
    'content': m.content,
    'seq': m.seq,
    'status': m.status.name,
    'retryCount': m.retryCount,
    'createdAt': m.createdAt.toUtc().toIso8601String(),
  };

  ChatMessage _messageFromJson(Map<String, dynamic> data) => ChatMessage(
    id: data['id'] as String,
    sessionId: data['sessionId'] as String,
    role: ChatRole.values.byName(data['role'] as String),
    content: data['content'] as String,
    seq: data['seq'] as int,
    status: ChatMessageStatus.values.byName(data['status'] as String),
    retryCount: data['retryCount'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
  );
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/routing/app_routes.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_bloc.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_event.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_state.dart';
import 'package:cerne/features/vault/presentation/widgets/pin_keypad.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

/// Which entry point opened `VaultPage` — decides the eventual unlocked
/// transition: `go(home)` for [gatekeeper], `pop()` for [relock]
/// (data-model.md State transitions).
enum VaultMode { gatekeeper, relock }

/// The single vault screen (research.md R4) — internally covers first-time
/// PIN setup, the biometric prompt, PIN-entry unlock/fallback, and the
/// biometrics opt-in as `VaultBloc` sub-states.
class VaultPage extends StatefulWidget {
  const VaultPage({required this.mode, super.key});

  final VaultMode mode;

  @override
  State<VaultPage> createState() => _VaultPageState();
}

class _VaultPageState extends State<VaultPage> {
  @override
  void initState() {
    super.initState();
    context.read<VaultBloc>().add(const VaultOpened());
  }

  void _useEmailPassword() => context.push(AppRoutes.login);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: SafeArea(
        child: BlocConsumer<VaultBloc, VaultState>(
          listenWhen: (previous, current) => current is VaultUnlocked,
          listener: (context, state) {
            if (widget.mode == VaultMode.gatekeeper) {
              context.go(AppRoutes.home);
            } else {
              Navigator.of(context).pop();
            }
          },
          builder: (context, state) {
            return switch (state) {
              VaultInitial() => const _LoadingView(),
              VaultPinSetupCreate() => _PinSetupCreateView(state: state),
              VaultPinSetupConfirm() => _PinSetupConfirmView(state: state),
              VaultBiometricOptIn() => const _BiometricOptInView(),
              VaultBiometricPrompting() => _BiometricPromptingView(
                  onUseEmailPassword: _useEmailPassword,
                ),
              VaultPinEntry() => _PinEntryView(
                  state: state,
                  onUseEmailPassword: _useEmailPassword,
                ),
              VaultUnlocked() => const SizedBox.shrink(),
            };
          },
        ),
      ),
    );
  }
}

class _LoadingView extends StatelessWidget {
  const _LoadingView();

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

class _UseEmailPasswordLink extends StatelessWidget {
  const _UseEmailPasswordLink({required this.onPressed});

  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    return TextButton(
      onPressed: onPressed,
      child: const Text('usar e-mail e senha'),
    );
  }
}

class _BiometricPromptingView extends StatelessWidget {
  const _BiometricPromptingView({required this.onUseEmailPassword});

  final VoidCallback onUseEmailPassword;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return Stack(
      children: [
        Center(
          child: Padding(
            padding: const EdgeInsets.symmetric(
              horizontal: DesignTokens.spacingXl,
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                GestureDetector(
                  onTap: () => bloc.add(const BiometricAuthRequested()),
                  child: Container(
                    width: DesignTokens.sizeBiometricIconContainer,
                    height: DesignTokens.sizeBiometricIconContainer,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: DesignTokens.colorSurfaceElevated,
                      border: Border.all(
                        color: DesignTokens.colorBorder,
                        width: DesignTokens.borderWidthFocused,
                      ),
                      boxShadow: DesignTokens.elevation1,
                    ),
                    child: Icon(
                      Icons.fingerprint,
                      size: DesignTokens.sizeBiometricIcon,
                      color: DesignTokens.colorPrimary,
                    ),
                  ),
                ),
                const SizedBox(height: DesignTokens.spacingLg),
                Text('Toque para desbloquear', style: DesignTokens.textTitleLg),
                const SizedBox(height: DesignTokens.spacingSm),
                Text(
                  'Use Face ID ou Touch ID para continuar',
                  textAlign: TextAlign.center,
                  style: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                ),
                const SizedBox(height: DesignTokens.spacingLg),
                TextButton(
                  onPressed: () => bloc.add(const UsePinRequested()),
                  child: Text(
                    'Usar PIN',
                    style: DesignTokens.textMonoCaption.copyWith(
                      color: DesignTokens.colorTextSecondary,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        Positioned(
          left: 0,
          right: 0,
          bottom: DesignTokens.spacing2xl,
          child: Center(
            child: _UseEmailPasswordLink(onPressed: onUseEmailPassword),
          ),
        ),
      ],
    );
  }
}

class _PinEntryView extends StatelessWidget {
  const _PinEntryView({required this.state, required this.onUseEmailPassword});

  final VaultPinEntry state;
  final VoidCallback onUseEmailPassword;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Digite seu PIN', style: DesignTokens.textTitleLg),
          if (state.errorMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            _PinErrorBand(message: state.errorMessage!),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          _UseEmailPasswordLink(onPressed: onUseEmailPassword),
        ],
      ),
    );
  }
}

class _PinErrorBand extends StatelessWidget {
  const _PinErrorBand({required this.message});

  final String message;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(
        horizontal: DesignTokens.spacingMd,
        vertical: DesignTokens.spacingSm,
      ),
      decoration: BoxDecoration(
        color: DesignTokens.colorError.withValues(alpha: 0.08),
        borderRadius: BorderRadius.circular(DesignTokens.radiusSm),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            Icons.error_outline,
            size: DesignTokens.spacingMd,
            color: DesignTokens.colorError,
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          Flexible(
            child: Text(
              message,
              style: DesignTokens.textLabelMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _PinSetupCreateView extends StatelessWidget {
  const _PinSetupCreateView({required this.state});

  final VaultPinSetupCreate state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Crie seu PIN', style: DesignTokens.textTitleSm),
          if (state.mismatchMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              state.mismatchMessage!,
              textAlign: TextAlign.center,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
        ],
      ),
    );
  }
}

class _PinSetupConfirmView extends StatelessWidget {
  const _PinSetupConfirmView({required this.state});

  final VaultPinSetupConfirm state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Confirme seu PIN', style: DesignTokens.textTitleSm),
          const SizedBox(height: DesignTokens.spacingLg),
          PinKeypad(
            enteredDigits: state.enteredDigits,
            onDigitPressed: (digit) => bloc.add(PinDigitEntered(digit)),
            onBackspacePressed: () =>
                bloc.add(const PinBackspacePressed()),
          ),
        ],
      ),
    );
  }
}

class _BiometricOptInView extends StatelessWidget {
  const _BiometricOptInView();

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<VaultBloc>();
    return SingleChildScrollView(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            Icons.fingerprint,
            size: DesignTokens.spacing2xl * 2,
            color: DesignTokens.colorPrimary,
          ),
          const SizedBox(height: DesignTokens.spacingLg),
          Text('Usar Face ID / Touch ID?', style: DesignTokens.textTitleSm),
          const SizedBox(height: DesignTokens.spacingLg),
          ElevatedButton(
            onPressed: () =>
                bloc.add(const BiometricOptInToggled(true)),
            child: const Text('Ativar'),
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          TextButton(
            onPressed: () =>
                bloc.add(const BiometricOptInToggled(false)),
            child: const Text('Agora não'),
          ),
        ],
      ),
    );
  }
}

