9	
10	/// Wraps [EntriesRemoteDataSource] and owns [cachedEntries] — an in-memory
11	/// mirror, backed by [EntriesLocalCache], of every entry this process has
12	/// seen (via a successful [create]/[list]/[search]), so it survives an app
13	/// restart. Registered as a `get_it` `lazySingleton` so the cache survives
14	/// across modal opens (same lifetime pattern as RF03's `VaultRepository`).
15	/// Read back out for display by `RecordsBloc` when a fetch fails outright —
16	/// the on-device fallback the PRD's "local read cache" describes
17	/// (requirements.md line 50/125).
18	class EntriesRepositoryImpl implements EntriesRepository {
19	  EntriesRepositoryImpl(
20	    this._remoteDataSource, {
21	    required this._sessionRepository,
22	    required this._localCache,
23	  });
24	
25	  final EntriesRemoteDataSource _remoteDataSource;
26	  final SessionRepository _sessionRepository;
27	  final EntriesLocalCache _localCache;
28	
29	  final List<Entry> _cachedEntries = [];
30	  Future<void>? _localCacheLoad;
31	
32	  // Runs once per process; every public method awaits it before touching
33	  // `_cachedEntries`, so the persisted cache is always merged in before
34	  // either a remote call resolves or `cachedEntries` is read back out —
35	  // closing the race between "app just launched" and "first read of the
36	  // cache."
37	  Future<void> _ensureLocalCacheLoaded() {
38	    return _localCacheLoad ??= _localCache.readAll().then(_mergeEntries);
39	  }
40	
41	  void _mergeEntries(List<Entry> fetched) {
42	    for (final entry in fetched) {
43	      final index = _cachedEntries.indexWhere((e) => e.id == entry.id);
44	      if (index >= 0) {
45	        _cachedEntries[index] = entry;
46	      } else {
47	        _cachedEntries.add(entry);
48	      }
49	    }
50	  }
51	
52	  Future<void> _cacheAndPersist(List<Entry> fetched) async {
53	    _mergeEntries(fetched);
54	    await _localCache.writeAll(_cachedEntries);
55	  }
56	
57	  @override
58	  Future<Either<Failure, Entry>> create({
59	    required String content,
60	    required EntrySource source,
61	    String? chatMessageId,
62	    DateTime? occurredAt,
63	  }) async {
64	    await _ensureLocalCacheLoaded();
65	    final result = await _remoteDataSource.create(
66	      content: content,
67	      source: source,
68	      chatMessageId: chatMessageId,
69	      occurredAt: occurredAt,
70	    );
71	    return result.match(
72	      (failure) => Future.value(Left(failure)),
73	      (entry) async {
74	        await _cacheAndPersist([entry]);
75	        return Right(entry);
76	      },
77	    );
78	  }
79	
80	  @override
81	  List<Entry> get cachedEntries => List.unmodifiable(_cachedEntries);
82	
83	  @override
84	  Future<Either<Failure, EntriesPage>> list({
85	    String? cursor,
86	    EntrySource? source,
87	    DateTime? dateFrom,
88	    DateTime? dateTo,
89	    int? limit,
90	  }) async {
91	    await _ensureLocalCacheLoaded();
92	    Future<Either<Failure, EntriesPage>> fetch() => _remoteDataSource.list(
93	      cursor: cursor,
94	      source: source,
95	      dateFrom: dateFrom,
96	      dateTo: dateTo,
97	      limit: limit,
98	    );
99	    final result = await fetch();
100	    final Either<Failure, EntriesPage> afterRetry = await result.match(
101	      (failure) => failure is AuthExpiredFailure
102	          ? _retryAfterSilentRefresh(fetch)
103	          : Future.value(Left(failure)),
104	      (page) => Future.value(Right(page)),
105	    );
106	    return afterRetry.match(
107	      (failure) => Future.value(Left(failure)),
108	      (page) async {
109	        await _cacheAndPersist(page.entries);
110	        return Right(page);
111	      },
112	    );
113	  }
114	
115	  @override
116	  Future<Either<Failure, List<Entry>>> search({
117	    String? q,
118	    EntrySource? source,
119	    DateTime? dateFrom,
120	    DateTime? dateTo,
121	    int limit = 50,
122	  }) async {
123	    await _ensureLocalCacheLoaded();
124	    Future<Either<Failure, List<Entry>>> fetch() => _remoteDataSource.search(
125	      q: q,
126	      source: source,
127	      dateFrom: dateFrom,
128	      dateTo: dateTo,
129	      limit: limit,
130	    );
131	    final result = await fetch();
132	    final Either<Failure, List<Entry>> afterRetry = await result.match(
133	      (failure) => failure is AuthExpiredFailure
134	          ? _retryAfterSilentRefresh(fetch)
135	          : Future.value(Left(failure)),
136	      (entries) => Future.value(Right(entries)),
137	    );
138	    return afterRetry.match(
139	      (failure) => Future.value(Left(failure)),
140	      (entries) async {
141	        await _cacheAndPersist(entries);
142	        return Right(entries);
143	      },
144	    );
145	  }
146	
147	  @override
148	  Future<Either<Failure, Entry>> getById(String id) async {
149	    final result = await _remoteDataSource.getById(id);
150	    return result.match(
151	      (failure) => failure is AuthExpiredFailure
152	          ? _retryAfterSilentRefresh(() => _remoteDataSource.getById(id))
153	          : Future.value(Left(failure)),
154	      (entry) => Future.value(Right(entry)),
155	    );
156	  }
157	
158	  // Exactly one retry. If it also comes back `AuthExpiredFailure` (a
159	  // pathological double-expiry), that is returned as-is — no second refresh
160	  // attempt, no loop (research.md R4, contracts/entries-repository-extension.md).
161	  Future<Either<Failure, T>> _retryAfterSilentRefresh<T>(
162	    Future<Either<Failure, T>> Function() retry,
163	  ) async {
164	    final refreshed = await _sessionRepository.refresh();
165	    return refreshed.match(
166	      (_) => Future.value(
167	        const Left(
168	          AuthExpiredFailure(message: 'Session could not be renewed', requestId: ''),
169	        ),
170	      ),
171	      (_) => retry(),
172	    );
173	  }
174	}
